def migrate_site_agreements(apps, schema_editor):
    """Copy each site's old per-site agreement to every APPROVED contractor of
    that site as an AGREEMENT v1 document. Sites with no contracted worker are
    skipped (the document becomes uploadable once a contractor is bound)."""
    Site = apps.get_model("bss_core", "Site")
    Allotment = apps.get_model("bss_core", "ContractorSiteAllotment")
    CSD = apps.get_model("bss_core", "ContractorSiteDocument")

    for site in Site.objects.all().iterator():
        stored = getattr(site.agreement_file, "name", site.agreement_file) or ""
        if not stored:
            continue
        name = (site.agreement_name or stored.split("/")[-1] or "agreement.pdf")[:255]
        approved = (Allotment.objects
                    .filter(site_id=site.id, status="APPROVED")
                    .select_related("binding"))
        for a in approved:
            contractor_id = getattr(a.binding, "contractor_id", None)
            if not contractor_id:
                continue
            CSD.objects.get_or_create(
                contractor_id=contractor_id, site_id=site.id,
                doc_type="AGREEMENT", version=1,
                defaults={"file": stored, "file_name": name, "is_current": True,
                          "uploaded_by_id": site.agreement_uploaded_by_id})


